/** Retain the active cache and the previous two releases for still-open PWA tabs. */
export const RETAINED_PWA_RELEASES = 3;
export const PWA_CACHE_PREFIX = 'ecm-';

/** This file is generated by Vite from the *same* build as the hashed application scripts. */
export const PWA_ASSET_MANIFEST = './pwa-assets.json';

export function appPrecacheAssets(manifest: unknown): string[] {
  if (!manifest || typeof manifest !== 'object' || !('assets' in manifest) || !Array.isArray(manifest.assets)) {
    throw new Error('Invalid PWA asset manifest');
  }
  const assets = manifest.assets as unknown[];
  if (!assets.length || assets.some(asset => typeof asset !== 'string' || !/^\.\/assets\/[a-zA-Z0-9_./-]+\.(?:js|css)$/.test(asset))) {
    throw new Error('PWA asset manifest has no valid JavaScript/CSS assets');
  }
  return [...new Set(assets as string[])];
}

/** CacheStorage.keys() is ordered from oldest to newest, not by semantic version. */
export function obsoletePwaCaches(
  cacheNames: readonly string[],
  current: string,
  retainedReleases = RETAINED_PWA_RELEASES,
): string[] {
  const previous = cacheNames.filter(name => name.startsWith(PWA_CACHE_PREFIX) && name !== current);
  return previous.slice(0, Math.max(0, previous.length - (retainedReleases - 1)));
}
